require_once 'includes/auth.php'; wajib_login(['admin','petugas']); $namaHalaman='Laporan Peminjaman';
$q=mysqli_query($koneksi,"SELECT p.*,u.nama,a.nama_alat FROM peminjaman p JOIN user u ON u.id_user=p.id_user JOIN alat a ON a.id_alat=p.id_alat ORDER BY p.id_peminjaman DESC");
require 'includes/header.php'; ?><h2>Laporan Peminjaman</h2><div class="panel"><button class="btn btn-outline-primary mb-3" onclick="window.print()">Cetak Laporan</button><div class="table-responsive"><table class="table"><thead><tr><th>Peminjam</th><th>Alat</th><th>Tanggal Pinjam</th><th>Tanggal Kembali</th><th>Jumlah</th><th>Status</th></tr></thead><tbody><?php while($p=mysqli_fetch_assoc($q)): ?><tr><td><?= e($p['nama']) ?></td><td><?= e($p['nama_alat']) ?></td><td><?= e($p['tanggal_pinjam']) ?></td><td><?= e($p['tanggal_kembali']?:'-') ?></td><td><?= (int)$p['jumlah'] ?></td><td><?= e($p['status']) ?></td></tr><?php endwhile; ?></tbody></table></div></div><?php require 'includes/footer.php'; ?>
